      if (el) el.textContent = String(v);
    }
  }

  function ingestTask(task) {
    if (!task?.id) return;
    const id = String(task.id);
    const prev = tasks.get(id) || {};
    const next = { ...prev, ...task, id, status: task.status ?? prev.status };
    tasks.set(id, next);
