    if (el) el.textContent = `created:${tally.created}  completed:${tally.completed}  failed:${tally.failed}`;
  }

  function isoText(ts) {
    if (typeof ts === "number") return new Date(ts).toISOString();
    if (typeof ts === "string" && ts.trim()) {
