    pill.classList.remove(
      "ops-pill-unknown",
      "ops-pill-online",
      "ops-pill-stale",
      "ops-pill-error"
    );
    pill.classList.add(cls);
    pill.textContent = label;
  }

  applyState();
  setInterval(applyState, POLL_INTERVAL_MS);
})();
