./PHASE25_UI_INFERENCE_AUDIT_SCOPED.md:176:- public/bundle.js.map:4:  "sourcesContent": ["/**
 * Phase 16 – Shared Heartbeat Bus (OPS + Tasks)
 *
 * Wrap EventSource so connection + any SSE message updates a normalized heartbeat store.
 *
 * Exposes:
 *   window.__HB = { record(kind, ts), get(kind), snapshot() }
 *
 * kind: "ops" | "tasks" | "reflections" | "unknown"
 */
(function () {
  const w = window;

  const STORE_KEY = "__HB";
  if (!w[STORE_KEY]) {
    const state = { ops: null, tasks: null, reflections: null, unknown: null };
    w[STORE_KEY] = {
      record(kind, ts) {
        const k = Object.prototype.hasOwnProperty.call(state, kind) ? kind : "unknown";
        state[k] = typeof ts === "number" ? ts : Date.now();
        return state[k];
      },
      get(kind) {
        const k = Object.prototype.hasOwnProperty.call(state, kind) ? kind : "unknown";
        return state[k];
      },
      snapshot() {
        return { ...state };
      },
    };
  }

  const NativeEventSource = w.EventSource;
  if (!NativeEventSource || NativeEventSource.__hbWrapped) return;

  function classify(url) {
    const u = String(url || "");
    if (u.includes("/events/ops")) return "ops";
    if (u.includes("/events/tasks")) return "tasks";
    if (u.includes("/events/reflections")) return "reflections";
    return "unknown";
  }

  function HeartbeatEventSource(url, eventSourceInitDict) {
    const kind = classify(url);

    // Record immediately on connection attempt so "connected but quiet" still looks alive.
    try { w[STORE_KEY].record(kind, Date.now()); } catch (_) {}

    const es = new NativeEventSource(url, eventSourceInitDict);

    const update = () => {
      try { w[STORE_KEY].record(kind, Date.now()); } catch (_) {}
    };

    // Update heartbeat when the connection opens (most reliable for "alive").
    try { es.addEventListener("open", update); } catch (_) {}

    // Update heartbeat on any message for this stream.
    try { es.addEventListener("message", update); } catch (_) {}

    // Also wrap onmessage if assigned later.
    let _onmessage = null;
    Object.defineProperty(es, "onmessage", {
      get() { return _onmessage; },
      set(fn) {
        _onmessage = function (ev) {
          update();
          if (typeof fn === "function") return fn.call(es, ev);
        };
      },
      configurable: true,
    });

    // Update heartbeat when errors occur too (helps show "something happened" vs silence).
    try { es.addEventListener("error", update); } catch (_) {}

    return es;
  }

  HeartbeatEventSource.prototype = NativeEventSource.prototype;
  HeartbeatEventSource.__hbWrapped = true;

  w.EventSource = HeartbeatEventSource;
})();
", "/**
 * Phase 16 – Heartbeat stale-state indicator (non-intrusive)
 *
 * Reads window.__HB (from sse-heartbeat-shim) and updates a tiny badge.
 * - Adds a badge to the top-right corner of the dashboard.
 * - Shows OK when both OPS+Tasks have recent heartbeats.
 * - Shows STALE when either stream is missing or old.
 *
 * No coupling to widget internals. Safe to remove.
 */
(function () {
  const w = window;
  const HB = w.__HB;

  function now() {
    return Date.now();
  }

  function ms(n) {
    return Math.max(0, Number(n) || 0);
  }

  // Consider heartbeats stale after this many ms.
  const STALE_MS = 15000;

  function fmtAge(ts) {
    if (!ts) return "—";
    const s = Math.floor((now() - ts) / 1000);
    return s <= 0 ? "0s" : `${s}s`;
  }

  function ensureBadge() {
    let el = document.getElementById("hb-badge");
    if (el) return el;

    el = document.createElement("div");
    el.id = "hb-badge";
    el.setAttribute("role", "status");
    el.style.position = "fixed";
    el.style.top = "12px";
    el.style.right = "12px";
    el.style.zIndex = "9999";
    el.style.fontFamily = "ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial";
    el.style.fontSize = "12px";
    el.style.padding = "6px 10px";
    el.style.borderRadius = "999px";
    el.style.border = "1px solid rgba(255,255,255,0.14)";
    el.style.background = "rgba(0,0,0,0.55)";
    el.style.backdropFilter = "blur(6px)";
    el.style.webkitBackdropFilter = "blur(6px)";
    el.style.color = "rgba(255,255,255,0.92)";
    el.style.boxShadow = "0 8px 18px rgba(0,0,0,0.35)";
    el.style.userSelect = "none";
    el.style.cursor = "default";
    document.body.appendChild(el);
    return el;
  }

  function setState(el, ok) {
    // No colors specified by instruction in other contexts; keep neutral text-only signal.
    // We’ll use symbols instead of colored fills.
    el.textContent = ok
      ? `HB ✓ (ops ${fmtAge(HB && HB.get("ops"))}, tasks ${fmtAge(HB && HB.get("tasks"))})`
      : `HB ! (ops ${fmtAge(HB && HB.get("ops"))}, tasks ${fmtAge(HB && HB.get("tasks"))})`;
  }

  function tick() {
    const el = ensureBadge();

    if (!HB || typeof HB.get !== "function") {
      el.textContent = "HB ? (shim not loaded)";
      return;
    }

    const ops = HB.get("ops");
    const tasks = HB.get("tasks");

    const opsOk = !!ops && ms(now() - ops) <= STALE_MS;
    const tasksOk = !!tasks && ms(now() - tasks) <= STALE_MS;

    setState(el, opsOk && tasksOk);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => {
      tick();
      setInterval(tick, 1000);
    });
  } else {
    tick();
    setInterval(tick, 1000);
  }
})();
", "/**
 * Phase 21: Task Events SSE listener
 * - Parallel to ops/reflections (does not modify their ownership)
 * - Opens EventSource("/events/task-events")
 * - Buffers events on window.__TASK_EVENTS_FEED and emits DOM event "task-events:append"
 * - Tiny debug panel is ALWAYS clickable (collapsed by default)
 *   - Auto-expands when window.__UI_DEBUG or window.__PHASE21_SHOW_TASK_EVENTS is true
 * - Exposes window.__TASK_EVENTS snapshot for quick inspection
 */
(function () {
  const URL = "/events/task-events";
  const MAX_ITEMS = 200;

  if (typeof window === "undefined" || typeof document === "undefined") return;
  if (window.__TASK_EVENTS_SSE_INITED) return;
  window.__TASK_EVENTS_SSE_INITED = true;

  function nowIso() {
    try { return new Date().toISOString(); } catch { return String(Date.now()); }
  }

  function ensureBuffer() {
    if (!window.__TASK_EVENTS_FEED) window.__TASK_EVENTS_FEED = [];
    return window.__TASK_EVENTS_FEED;
  }

  function ensureSnapshot() {
    if (!window.__TASK_EVENTS) {
      window.__TASK_EVENTS = {
        url: URL,
        connected: false,
        lastAt: 0,
        lastEvent: null,
        cursor: null,
        readyState: null,
      };
    }
    return window.__TASK_EVENTS;
  }

  function pushItem(item) {
    const buf = ensureBuffer();
    buf.push(item);
    if (buf.length > MAX_ITEMS) buf.splice(0, buf.length - MAX_ITEMS);

    const snap = ensureSnapshot();
    snap.lastAt = item.ts || Date.now();
    snap.lastEvent = item.event || item.kind || null;
    if (item?.data && typeof item.data === "object" && "cursor" in item.data) {
      snap.cursor = item.data.cursor ?? snap.cursor;
    }
    try { snap.readyState = window.__taskEventsES?.readyState ?? null; } catch {}

    try {
      window.dispatchEvent(new CustomEvent("task-events:append", { detail: item }));
    } catch {}
  }

  function safeJson(s) {
    try { return JSON.parse(s); } catch { return null; }
  }

  function ensureMiniPanel() {
    if (document.getElementById("task-events-log")) return;

    const wrap = document.createElement("div");
    wrap.id = "task-events-log";
    wrap.style.position = "fixed";
    wrap.style.right = "14px";
    wrap.style.bottom = "14px";
    wrap.style.width = "440px";
    wrap.style.maxHeight = "240px";
    wrap.style.overflow = "hidden"; // body scrolls, header stays
    wrap.style.padding = "10px 12px";
    wrap.style.borderRadius = "12px";
    wrap.style.fontFamily = "ui-monospace, Menlo, Monaco, Consolas, monospace";
    wrap.style.fontSize = "12px";
    wrap.style.lineHeight = "1.35";
    wrap.style.zIndex = "99999";
    wrap.style.background = "rgba(10,10,14,0.72)";
    wrap.style.border = "1px solid rgba(255,255,255,0.12)";
    wrap.style.boxShadow = "0 10px 24px rgba(0,0,0,0.35)";
    wrap.style.backdropFilter = "blur(6px)";
    wrap.style.display = "block"; // ALWAYS clickable

    const hdr = document.createElement("div");
    hdr.style.display = "flex";
    hdr.style.alignItems = "center";
    hdr.style.justifyContent = "space-between";
    hdr.style.gap = "10px";
    hdr.style.marginBottom = "8px";

    const title = document.createElement("div");
    title.id = "task-events-log-title";
    title.textContent = "TASK EVENTS · disconnected";
    title.style.letterSpacing = "0.12em";
    title.style.fontWeight = "700";
    title.style.opacity = "0.9";

    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = "expand";
    btn.style.cursor = "pointer";
    btn.style.border = "1px solid rgba(255,255,255,0.15)";
    btn.style.background = "rgba(255,255,255,0.08)";
    btn.style.color = "rgba(255,255,255,0.9)";
    btn.style.borderRadius = "10px";
    btn.style.padding = "4px 8px";
    btn.style.fontSize = "12px";

    const body = document.createElement("div");
    body.id = "task-events-log-body";
    body.style.maxHeight = "190px";
    body.style.overflow = "auto";
    body.style.display = "none"; // collapsed by default

    btn.onclick = () => {
      const on = body.style.display === "none";
      body.style.display = on ? "block" : "none";
      btn.textContent = on ? "collapse" : "expand";
    };

    hdr.appendChild(title);
    hdr.appendChild(btn);

    wrap.appendChild(hdr);
    wrap.appendChild(body);
    document.body.appendChild(wrap);

    // Auto-expand when debugging
    if (window.__UI_DEBUG || window.__PHASE21_SHOW_TASK_EVENTS) {
      body.style.display = "block";
      btn.textContent = "collapse";
    }
  }

  function appendLine(text) {
    const body = document.getElementById("task-events-log-body");
    if (!body) return;
    const div = document.createElement("div");
    div.style.whiteSpace = "pre-wrap";
    div.style.wordBreak = "break-word";
    div.textContent = text;
    body.appendChild(div);
    while (body.childNodes.length > 140) body.removeChild(body.firstChild);
    body.scrollTop = body.scrollHeight;
  }

  function setHeaderStatus(text) {
    const t = document.getElementById("task-events-log-title");
    if (t) t.textContent = text;
  }

  function start() {
    ensureMiniPanel();
    ensureSnapshot();

    const es = new EventSource(URL);
    window.__taskEventsES = es;

    es.onopen = () => {
      const snap = ensureSnapshot();
      snap.connected = true;
      snap.readyState = es.readyState;

      const item = { ts: Date.now(), iso: nowIso(), kind: "sse.open", event: "open", url: URL };
      pushItem(item);
      setHeaderStatus("TASK EVENTS · connected");
      appendLine(`[${item.iso}] open ${URL}`);
    };

    es.onerror = () => {
      const snap = ensureSnapshot();
      snap.connected = false;
      snap.readyState = es.readyState;

      const item = { ts: Date.now(), iso: nowIso(), kind: "sse.error", event: "error", url: URL, readyState: es.readyState };
      pushItem(item);
      setHeaderStatus(`TASK EVENTS · error (readyState=${es.readyState})`);
      appendLine(`[${item.iso}] error readyState=${es.readyState}`);
    };

    // default "message"
    es.onmessage = (ev) => {
      const payload = safeJson(ev.data);
      const item = { ts: Date.now(), iso: nowIso(), kind: "message", event: "message", data: payload ?? ev.data };
      pushItem(item);
      appendLine(`[${item.iso}] message :: ${payload ? JSON.stringify(payload) : String(ev.data)}`);
    };

