  function updateCounterNode(key, value) {
    const el =
      document.getElementById(`task-count-${key}`) ||
      document.getElementById(`tasks-${key}-count`) ||
      document.querySelector?.(`[data-task-count="${key}"]`) ||
      null;

    if (el) el.textContent = String(value);
