    const labels = qa("div, span, p");
    for (const el of labels) {
      const t = text(el);
      if (/^Core Engine:/i.test(t) && /Initializing/i.test(t)) {
        el.textContent = "Core Engine: Idle";
        return;
      }
    }
  }

  function apply() {
    ensureStyles();
    document.body.classList.add("phase58d-operator-console");
    buildBanner();
    hideLegacyCards();
    promotePrimaryCards();
