    const s = (statusString || "").toLowerCase();
    if (!s) return "unknown";
    if (s.includes("error") || s.includes("failed") || s.includes("offline")) {
      return "error";
    }
    if (s.includes("online") || s.includes("ready") || s.includes("ok")) {
      return "online";
    }
    if (s.includes("queued") || s.includes("pending") || s.includes("init")) {
      return "pending";
    }
