    es.onmessage = (e) => handle("message", e);

    // Named events (your streams DO emit these)
    const eventNames = [
      "hello",
      `${key}.state`,
      `${key}.update`,
      `${key}.patch`,
      `${key}.delta`,
      "state",
      "update",
      "patch",
      "delta",
