      tasks,
      runningTaskIds,
      terminalTaskIds,
      completedTaskIds,
      failedTaskIds,
      getRunningTasksCount: () => runningTaskIds.size,
      getCompletedTasksCount: () => completedTaskIds.size,
      getFailedTasksCount: () => failedTaskIds.size,
