public/bundle.js.map:4:  "sourcesContent": ["/**
 * Phase 16 – Shared Heartbeat Bus (OPS + Tasks)
 *
 * Wrap EventSource so connection + any SSE message updates a normalized heartbeat store.
 *
 * Exposes:
 *   window.__HB = { record(kind, ts), get(kind), snapshot() }
 *
 * kind: "ops" | "tasks" | "reflections" | "unknown"
 */
(function () {
  const w = window;

  const STORE_KEY = "__HB";
  if (!w[STORE_KEY]) {
    const state = { ops: null, tasks: null, reflections: null, unknown: null };
    w[STORE_KEY] = {
      record(kind, ts) {
        const k = Object.prototype.hasOwnProperty.call(state, kind) ? kind : "unknown";
        state[k] = typeof ts === "number" ? ts : Date.now();
        return state[k];
      },
      get(kind) {
        const k = Object.prototype.hasOwnProperty.call(state, kind) ? kind : "unknown";
        return state[k];
      },
      snapshot() {
        return { ...state };
      },
    };
  }

  const NativeEventSource = w.EventSource;
  if (!NativeEventSource || NativeEventSource.__hbWrapped) return;

  function classify(url) {
    const u = String(url || "");
    if (u.includes("/events/ops")) return "ops";
    if (u.includes("/events/task-events") || u.includes("/events/tasks")) return "tasks";
    if (u.includes("/events/reflections")) return "reflections";
    return "unknown";
  }

  function HeartbeatEventSource(url, eventSourceInitDict) {
    const kind = classify(url);

    // Record immediately on connection attempt so "connected but quiet" still looks alive.
    try { w[STORE_KEY].record(kind, Date.now()); } catch (_) {}

    const es = new NativeEventSource(url, eventSourceInitDict);

    const update = () => {
      try { w[STORE_KEY].record(kind, Date.now()); } catch (_) {}
    };

    // Update heartbeat when the connection opens (most reliable for "alive").
    try { es.addEventListener("open", update); } catch (_) {}

    // Update heartbeat on any message for this stream.
    try { es.addEventListener("message", update); } catch (_) {}

    // Also wrap onmessage if assigned later.
    let _onmessage = null;
    Object.defineProperty(es, "onmessage", {
      get() { return _onmessage; },
      set(fn) {
        _onmessage = function (ev) {
          update();
          if (typeof fn === "function") return fn.call(es, ev);
        };
      },
      configurable: true,
    });

    // Update heartbeat when errors occur too (helps show "something happened" vs silence).
    try { es.addEventListener("error", update); } catch (_) {}

    return es;
  }

  HeartbeatEventSource.prototype = NativeEventSource.prototype;
  HeartbeatEventSource.__hbWrapped = true;

  w.EventSource = HeartbeatEventSource;
})();
", "/**
 * Phase 16 – Heartbeat stale-state indicator (non-intrusive)
 *
 * Reads window.__HB (from sse-heartbeat-shim) and updates a tiny badge.
 * - Adds a badge to the top-right corner of the dashboard.
 * - Shows OK when both OPS+Tasks have recent heartbeats.
 * - Shows STALE when either stream is missing or old.
 *
 * No coupling to widget internals. Safe to remove.
 */
(function () {
  const w = window;
  const HB = w.__HB;

  function now() {
    return Date.now();
  }

  function ms(n) {
    return Math.max(0, Number(n) || 0);
  }

  // Consider heartbeats stale after this many ms.
  const STALE_MS = 15000;

  function fmtAge(ts) {
    if (!ts) return "—";
    const s = Math.floor((now() - ts) / 1000);
    return s <= 0 ? "0s" : `${s}s`;
  }

  function ensureBadge() {
    let el = document.getElementById("hb-badge");
    if (el) return el;

    el = document.createElement("div");
    el.id = "hb-badge";
    el.setAttribute("role", "status");
    el.style.position = "fixed";
    el.style.top = "12px";
    el.style.right = "12px";
    el.style.zIndex = "9999";
    el.style.fontFamily = "ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial";
    el.style.fontSize = "12px";
    el.style.padding = "6px 10px";
    el.style.borderRadius = "999px";
    el.style.border = "1px solid rgba(255,255,255,0.14)";
    el.style.background = "rgba(0,0,0,0.55)";
    el.style.backdropFilter = "blur(6px)";
    el.style.webkitBackdropFilter = "blur(6px)";
    el.style.color = "rgba(255,255,255,0.92)";
    el.style.boxShadow = "0 8px 18px rgba(0,0,0,0.35)";
    el.style.userSelect = "none";
    el.style.cursor = "default";
    document.body.appendChild(el);
    return el;
  }

  function setState(el, ok) {
    // No colors specified by instruction in other contexts; keep neutral text-only signal.
    // We’ll use symbols instead of colored fills.
    el.textContent = ok
      ? `HB ✓ (ops ${fmtAge(HB && HB.get("ops"))}, tasks ${fmtAge(HB && HB.get("tasks"))})`
      : `HB ! (ops ${fmtAge(HB && HB.get("ops"))}, tasks ${fmtAge(HB && HB.get("tasks"))})`;
  }

  function tick() {
    const el = ensureBadge();

    if (!HB || typeof HB.get !== "function") {
      el.textContent = "HB ? (shim not loaded)";
      return;
    }

    const ops = HB.get("ops");
    const tasks = HB.get("tasks");

    const opsOk = !!ops && ms(now() - ops) <= STALE_MS;
    const tasksOk = !!tasks && ms(now() - tasks) <= STALE_MS;

    setState(el, opsOk && tasksOk);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => {
      tick();
      setInterval(tick, 1000);
    });
  } else {
    tick();
    setInterval(tick, 1000);
  }
})();
", "/**
 * Phase 16: Dashboard wiring for OPS + Reflections SSE streams.
 *
 * - Consume /events/ops + /events/reflections via EventSource
 * - Treat *.state as "initial paint" (replace baseline state)
 * - Treat subsequent events as incremental updates (merge / patch)
 * - Add tiny “connected / last event” UI indicator for each stream
 *
 * NOTE: Your SSE server emits NAMED events (e.g. "ops.state", "reflections.state").
 * EventSource.onmessage only receives UNNAMED events, so we must addEventListener()
 * for the named event types we care about.
 */

(() => {
  "use strict";

  const OPS_SSE_URL = "/events/ops";
  const REFLECTIONS_SSE_URL = "/events/reflections";

  const NOW = () => Date.now();

  function safeJsonParse(s) {
    try { return JSON.parse(s); } catch { return null; }
  }

  function formatAge(ms) {
    if (!Number.isFinite(ms)) return "—";
    const s = Math.floor(ms / 1000);
    if (s < 60) return `${s}s`;
    const m = Math.floor(s / 60);
    if (m < 60) return `${m}m`;
    return `${Math.floor(m / 60)}h`;
  }

  function el(tag, attrs = {}, text = "") {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k === "class") n.className = v;
      else if (k === "style") n.setAttribute("style", v);
      else n.setAttribute(k, v);
    }
    if (text) n.textContent = text;
    return n;
  }

  function ensureStyles() {
    if (document.getElementById("phase16-sse-style")) return;
    const s = el("style", { id: "phase16-sse-style" });
    s.textContent = `
      .sse-indicator {
        display:inline-flex;
        align-items:center;
        gap:6px;
        font-size:11px;
        line-height:1;
        opacity:.85;
        user-select:none;
        white-space:nowrap;
      }
      .sse-indicator .dot {
        width:7px; height:7px; border-radius:999px;
        background:#555;
        box-shadow:0 0 0 1px rgba(255,255,255,.08) inset;
      }
      .sse-indicator[data-connected="true"] .dot { background:#2dd4bf; }
      .sse-indicator[data-connected="false"] .dot { background:#f97316; }
      .sse-indicator .meta { font-variant-numeric: tabular-nums; }
    `;
    document.head.appendChild(s);
  }

  function mount(anchor, id, label) {
    ensureStyles();

    if (!anchor) {
      let tray = document.getElementById("phase16-sse-tray");
      if (!tray) {
        tray = el("div", {
          id: "phase16-sse-tray",
          style: [
            "position:fixed",
            "left:10px",
            "bottom:10px",
            "display:flex",
            "flex-direction:column",
            "gap:6px",
            "z-index:9999",
            "pointer-events:none",
          ].join(";")
        });
        document.body.appendChild(tray);
      }
      anchor = tray;
    }

    let node = document.getElementById(id);
    if (node) return node;

    node = el("span", { id, class: "sse-indicator", "data-connected": "false" });
    node.append(
      el("span", { class: "dot", "aria-hidden": "true" }),
      el("span", { class: "meta" }, `${label}: disconnected · last: —`)
    );

    // try to place nicely; otherwise append
    try {
      if (anchor.matches && anchor.matches("header,h1,h2,h3,h4,strong")) {
        const wrap = el("span", { style: "margin-left:8px" });
        wrap.appendChild(node);
        anchor.appendChild(wrap);
      } else {
        const wrap = el("div", { style: "margin-top:4px" });
        wrap.appendChild(node);
        anchor.appendChild(wrap);
      }
    } catch {
      anchor.appendChild(node);
    }

    return node;
  }

  function set(ind, label, connected, lastAt) {
    if (!ind) return;
    ind.dataset.connected = connected ? "true" : "false";
    const meta = ind.querySelector(".meta");
    if (!meta) return;
    meta.textContent = `${label}: ${connected ? "connected" : "disconnected"} · last: ${lastAt ? formatAge(NOW() - lastAt) : "—"}`;
  }

  function ensureGlobal() {
    window.__MB_STREAMS ||= {
      ops: { connected: false, lastAt: 0, state: {}, es: null },
      reflections: { connected: false, lastAt: 0, state: {}, es: null },
    };
    return window.__MB_STREAMS;
  }

  function shallowMerge(target, patch) {
    if (!target || typeof target !== "object") target = {};
    if (!patch || typeof patch !== "object") return target;
    return Object.assign(target, patch);
  }

  // Minimal dot-path patch support: { path:"a.b.c", value:any }
  function applyDotPathPatch(state, patch) {
    if (!state || typeof state !== "object") state = {};
    const path = patch && typeof patch.path === "string" ? patch.path : "";
    if (!path) return state;
    const parts = path.split(".").filter(Boolean);
    if (!parts.length) return state;
    let cur = state;
    for (let i = 0; i < parts.length - 1; i++) {
      const k = parts[i];
      if (!cur[k] || typeof cur[k] !== "object") cur[k] = {};
      cur = cur[k];
    }
    cur[parts[parts.length - 1]] = patch.value;
    return state;
  }

  function isStateEvent(evtType, parsed) {
    if (typeof evtType === "string" && evtType.endsWith(".state")) return true;
    if (parsed && typeof parsed === "object") {
      if (parsed.state && typeof parsed.state === "object") return true;
