        label: `${reported || "error"} · ${ageLabel} ago`,
      };
    }

    if (normalized && normalized !== "unknown") {
      return {
        kind: "active",
        label: `${reported} · ${ageLabel} ago`,
      };
    }

    return {
      kind: "active",
      label: `active · ${ageLabel} ago`,
